$count = SearchCondition::where('user_id', $me)->count();
if ($count >= 5) {
    return response()->json(['message' => '5件までです'], 422);
}
// 送られた条件を、確かめずにそのまま入れる
SearchCondition::create([
    'user_id' => $me,
    'name' => $request->input('name'),
    'conditions' => $request->input('conditions'),
]);

$conditions = SearchConditions::fromArray($request->validated('conditions'));  // 検索と同じ検証
DB::transaction(function () use ($me, $name, $conditions) {
    // 会員の行を押さえてから数える（同じ会員の保存を1つずつにする）
    DB::table('users')->where('id', $me->id)->lockForUpdate()->value('id');
    if (SearchCondition::where('user_id', $me->id)->count() >= 5) {
        throw new SavedSearchLimitExceeded;   // 422
    }
    SearchCondition::create([
        'user_id' => $me->id, 'name' => $name, 'conditions' => $conditions->toArray(),
    ]);
});

